import { HistoricalDataService } from "./HistoricalDataService";
import { InstrumentMasterService, getInstrumentMasterService } from "./InstrumentMasterService";
import logger from "../utils/logger";
import { TechnicalIndicators } from "./TechnicalIndicators";
import type TickerClient from "./TickerClient";

export interface ScanResult {
  symbol: string;
  score: number;
  reason: string[];
  metrics: {
    price: number;
    atrPercent: number;
    volumeRatio: number;
    dailyRangePercent: number;
  };
}

export class MarketScannerService {
  private readonly instrumentService: InstrumentMasterService;
  private readonly historicalDataService: HistoricalDataService;

  // Nifty 50 + highly liquid midcaps for better volatility
  private readonly UNIVERSE = [
    "RELIANCE", "TCS", "HDFCBANK", "INFY", "ICICIBANK", "HINDUNILVR", "ITC", "SBIN", "BHARTIARTL", "KOTAKBANK",
    "LTIM", "AXISBANK", "BAJFINANCE", "ASIANPAINT", "MARUTI", "HCLTECH", "SUNPHARMA", "TITAN", "ULTRACEMCO", "TATASTEEL",
    "NTPC", "POWERGRID", "BAJAJFINSV", "INDUSINDBK", "NESTLEIND", "JSWSTEEL", "ADANIENT", "GRASIM", "TECHM", "ONGC",
    "HINDALCO", "WIPRO", "COALINDIA", "DIVISLAB", "ADANIPORTS", "CIPLA", "APOLLOHOSP", "DRREDDY", "M&M", "TATAMOTORS",
    "EICHERMOT", "BRITANNIA", "BAJAJ-AUTO", "HEROMOTOCO", "SBILIFE", "HDFCLIFE", "BPCL", "TATACONSUM", "UPL",
    "ADANIGREEN", "ADANIPOWER", "DLF", "HAL", "TATAELXSI", "TRENT", "VBL", "ZOMATO", "CANBK", "IDFCFIRSTB"
  ];

  constructor(
    historicalDataService: HistoricalDataService,
    instrumentService?: InstrumentMasterService
  ) {
    this.historicalDataService = historicalDataService;
    this.instrumentService = instrumentService || getInstrumentMasterService();
  }

  /**
   * Scan the market for high-volatility, high-volume stocks suitable for day trading
   */
  async scan(limit: number = 10): Promise<ScanResult[]> {
    logger.info({ universeSize: this.UNIVERSE.length }, "Starting intraday market scan...");

    if (!this.instrumentService.isReady()) {
      await this.instrumentService.loadInstrumentMaster();
    }

    const results: ScanResult[] = [];

    // Concurrency limit to avoid rate limiting
    const batchSize = 5;
    for (let i = 0; i < this.UNIVERSE.length; i += batchSize) {
      const batch = this.UNIVERSE.slice(i, i + batchSize);
      const batchResults = await Promise.allSettled(
        batch.map(symbol => this.analyzeForIntraday(symbol))
      );

      for (const result of batchResults) {
        if (result.status === "fulfilled" && result.value) {
          results.push(result.value);
        }
      }
    }

    // Sort by score (Volatility + Volume + Trend)
    const sortedResults = results.sort((a, b) => b.score - a.score).slice(0, limit);

    logger.info(
      { 
        scanned: this.UNIVERSE.length, 
        selected: sortedResults.length,
        topPicks: sortedResults.map(r => r.symbol)
      }, 
      "Intraday market scan completed"
    );

    return sortedResults;
  }

  private async analyzeForIntraday(symbol: string): Promise<ScanResult | null> {
    try {
      // Need at least 30 days of data for ATR and SMA
      const candles = await this.historicalDataService.getRecentData(symbol, 40);

      if (candles.length < 25) return null;

      const latest = candles[candles.length - 1];
      const prev = candles[candles.length - 2];
      const closes = candles.map(c => c.close);
      const volumes = candles.map(c => c.volume);

      // 1. ATR % Calculation (Volatility)
      const atrs = TechnicalIndicators.calculateATR(candles, 14);
      const currentAtr = atrs[atrs.length - 1];
      const atrPercent = (currentAtr / latest.close) * 100;

      // 2. Relative Volume (RVOL)
      const avgVolume = TechnicalIndicators.calculateSMA(volumes, 20);
      const volumeRatio = latest.volume / avgVolume;

      // 3. Daily Range %
      const dailyRangePercent = ((latest.high - latest.low) / latest.low) * 100;

      // 4. Trend Filter (Price > 20 SMA)
      const sma20 = TechnicalIndicators.calculateSMA(closes, 20);
      const isShortTermBullish = latest.close > sma20;

      // DAY TRADING CRITERIA:
      // - High ATR % (> 1.2% for movement)
      // - High RVOL (> 0.8 for interest)
      // - Bullish Trend

      if (atrPercent > 1.2 && volumeRatio > 0.8 && isShortTermBullish) {
        // Scoring: 40% ATR%, 40% RVOL, 20% Range
        const score = (atrPercent * 4) + (volumeRatio * 4) + (dailyRangePercent * 2);

        return {
          symbol,
          score,
          reason: [
            `High Volatility (ATR ${atrPercent.toFixed(2)}%)`,
            `Active Interest (RVOL ${volumeRatio.toFixed(2)})`,
            `Bullish Setup (> 20 SMA)`
          ],
          metrics: {
            price: latest.close,
            atrPercent,
            volumeRatio,
            dailyRangePercent
          }
        };
      }

      return null;
    } catch (error) {
      return null;
    }
  }

  /**
   * Automatically subscribe to picked stocks
   */
  async applyPicks(picks: ScanResult[], tickerClient: TickerClient): Promise<void> {
    if (picks.length === 0) {
      logger.warn("No stocks picked to apply");
      return;
    }

    let subscribedCount = 0;
    for (const pick of picks) {
      const token = this.instrumentService.getToken(pick.symbol, "NSE");
      if (token) {
        tickerClient.subscribe({
          exchange: "NSE",
          symbolToken: token,
          symbol: pick.symbol
        });
        subscribedCount++;
      } else {
        logger.warn({ symbol: pick.symbol }, "Failed to subscribe to picked stock: Token not found");
      }
    }

    logger.info({ count: subscribedCount }, "Subscribed to automatically picked stocks");
  }
}

export default MarketScannerService;

/**
 * Abstract ticker client interface for real-time market data streaming
 * Allows different broker ticker implementations to be used interchangeably
 */

export interface TickerSubscription {
    exchange: string;
    symbolToken: string;
    symbol: string;
}

export interface TickerClient {
    /**
     * Connect to the ticker WebSocket
     */
    connect(): Promise<void>;

    /**
     * Disconnect from the ticker WebSocket
     */
    disconnect(): Promise<void>;

    /**
     * Check if the ticker is currently connected
     */
    isConnected(): boolean;

    /**
     * Subscribe to real-time updates for a symbol
     */
    subscribe(subscription: TickerSubscription): void;

    /**
     * Unsubscribe from updates for a symbol
     */
    unsubscribe(exchange: string, symbolToken: string): void;
}

export default TickerClient;

import WebSocket from "ws";
import type { MarketDataService } from "./MarketDataService";
import type { TickerClient, TickerSubscription } from "./TickerClient";
import logger from "../utils/logger";
import { loadAngelToken } from "../routes/auth";

interface AngelOneTickMessage {
  exchange: string;
  symbolToken: string;
  ltp?: number;
  lastPrice?: number;
  volume?: number;
  avgPrice?: number;
  [key: string]: unknown;
}

/**
 * Angel One WebSocket ticker service for live market data
 * Subscribes to real-time price updates and feeds them to MarketDataService
 */
export class AngelOneTickerService implements TickerClient {
  private ws?: WebSocket;
  private marketDataService: MarketDataService;
  private subscriptions: Map<string, TickerSubscription> = new Map();
  private reconnectTimer?: NodeJS.Timeout;
  private heartbeatInterval?: NodeJS.Timeout;
  private _connected = false;
  private currentTokens?: { clientId: string; jwtToken: string; feedToken: string };
  private reconnectAttempts = 0;

  private readonly WS_URL = "wss://smartapisocket.angelone.in/smart-stream";
  private readonly HEARTBEAT_INTERVAL = 10000; // 10 seconds
  private readonly RECONNECT_DELAY = 5000; // 5 seconds
  private readonly MAX_RECONNECT_ATTEMPTS = 10; // Stop retrying after 10 failures

  constructor(marketDataService: MarketDataService) {
    this.marketDataService = marketDataService;
  }

  /**
   * Connect to Angel One WebSocket and authenticate
   */
  async connect(): Promise<void> {
    if (this._connected) {
      logger.info("Angel One ticker already connected");
      return;
    }

    try {
      // Load latest tokens
      const tokenData = await loadAngelToken();
      if (!tokenData) {
        throw new Error("No Angel One tokens found. Cannot connect ticker.");
      }

      this.currentTokens = {
        clientId: tokenData.clientId,
        jwtToken: tokenData.jwtToken,
        feedToken: tokenData.feedToken,
      };

      // Get API key from env
      const apiKey = process.env.ANGEL_ONE_API_KEY || "";

      // Angel One SmartAPI WebSocket requires headers during handshake
      const wsOptions = {
        headers: {
          "Authorization": `Bearer ${tokenData.jwtToken}`,
          "x-api-key": apiKey,
          "x-client-code": tokenData.clientId,
          "x-feed-token": tokenData.feedToken,
        }
      };

      this.ws = new WebSocket(this.WS_URL, wsOptions);

      this.ws.on("open", () => this.onOpen());
      this.ws.on("message", (data) => this.onMessage(data));
      this.ws.on("error", (error) => this.onError(error));
      this.ws.on("close", () => this.onClose());

      logger.info("Connecting to Angel One WebSocket ticker...");
    } catch (error) {
      logger.error({ err: error }, "Failed to connect to Angel One WebSocket");
      throw error;
    }
  }

  /**
   * Disconnect from WebSocket
   */
  async disconnect(): Promise<void> {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
    }

    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
    }

    if (this.ws) {
      this.ws.close();
      this.ws = undefined;
    }

    this._connected = false;
    this.subscriptions.clear();
    logger.info("Angel One ticker disconnected");
  }

  /**
   * Subscribe to ticker updates for a symbol
   */
  subscribe(subscription: TickerSubscription): void {
    const key = `${subscription.exchange}:${subscription.symbolToken}`;
    this.subscriptions.set(key, subscription);

    if (this._connected && this.ws) {
      this.sendSubscription([subscription], "subscribe");
    }
  }

  /**
   * Unsubscribe from ticker updates for a symbol
   */
  unsubscribe(exchange: string, symbolToken: string): void {
    const key = `${exchange}:${symbolToken}`;
    const subscription = this.subscriptions.get(key);

    if (subscription) {
      this.subscriptions.delete(key);

      if (this._connected && this.ws) {
        this.sendSubscription([subscription], "unsubscribe");
      }
    }
  }

  /**
   * Check if ticker is connected
   * Implements TickerClient.isConnected()
   */
  isConnected(): boolean {
    return this._connected;
  }

  /**
   * Handle WebSocket open event
   */
  private onOpen(): void {
    logger.info("Angel One WebSocket connected");

    // Authenticate
    this.authenticate();

    // Start heartbeat
    this.startHeartbeat();
  }

  /**
   * Handle WebSocket message event
   */
  private onMessage(data: WebSocket.Data): void {
    try {
      const message = JSON.parse(data.toString());

      // Handle different message types
      if (message.action === "heartbeat") {
        // Heartbeat acknowledgment
        return;
      }

      if (message.action === "subscribe" || message.action === "unsubscribe") {
        logger.debug({ action: message.action }, "Subscription action completed");
        return;
      }

      // Market data update
      if (message.data && Array.isArray(message.data)) {
        this.processMarketData(message.data);
      }
    } catch (error) {
      logger.error({ err: error, data: data.toString() }, "Error processing WebSocket message");
    }
  }

  /**
   * Handle WebSocket error event
   */
  private onError(error: Error): void {
    logger.error({ err: error }, "Angel One WebSocket error");
  }

  /**
   * Handle WebSocket close event
   */
  private onClose(): void {
    logger.warn("Angel One WebSocket connection closed");

    this._connected = false;

    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
    }

    // Attempt to reconnect
    this.scheduleReconnect();
  }

  /**
   * Authenticate with Angel One WebSocket
   */
  private authenticate(): void {
    if (!this.ws || !this.currentTokens) {
      return;
    }

    const authMessage = {
      action: "authenticate",
      clientId: this.currentTokens.clientId,
      jwtToken: this.currentTokens.jwtToken,
      feedToken: this.currentTokens.feedToken,
    };

    this.ws.send(JSON.stringify(authMessage));

    // Set connected flag after sending auth
    // (we'll assume success for now, proper error handling would check response)
    this._connected = true;

    // Reset retry counter on successful connection
    this.reconnectAttempts = 0;

    // Resubscribe to all previous subscriptions
    if (this.subscriptions.size > 0) {
      this.sendSubscription(Array.from(this.subscriptions.values()), "subscribe");
    }

    logger.info("Angel One WebSocket authenticated");
  }

  /**
   * Send subscription/unsubscription message
   */
  private sendSubscription(
    subscriptions: TickerSubscription[],
    action: "subscribe" | "unsubscribe"
  ): void {
    if (!this.ws || !this._connected) {
      logger.warn("Cannot send subscription: WebSocket not connected");
      return;
    }

    const message = {
      action,
      mode: "FULL", // FULL mode includes depth data
      exchangeType: subscriptions.map((sub) => sub.exchange),
      tokens: subscriptions.map((sub) => sub.symbolToken),
    };

    this.ws.send(JSON.stringify(message));

    logger.info(
      { action, count: subscriptions.length },
      "Sent subscription message to Angel One"
    );
  }

  /**
   * Process market data updates
   */
  private processMarketData(data: AngelOneTickMessage[]): void {
    for (const tick of data) {
      try {
        // Find the subscription for this tick
        const key = `${tick.exchange}:${tick.symbolToken}`;
        const subscription = this.subscriptions.get(key);

        if (!subscription) {
          continue;
        }

        // Update market data service
        this.marketDataService.updateTick({
          symbol: subscription.symbol,
          price: tick.ltp || tick.lastPrice || 0,
          volume: tick.volume || 0,
          averagePrice: tick.avgPrice,
          timestamp: new Date(),
        });

        logger.debug(
          { symbol: subscription.symbol, price: tick.ltp, volume: tick.volume },
          "Market data updated"
        );
      } catch (error) {
        logger.error({ err: error, tick }, "Error processing market tick");
      }
    }
  }

  /**
   * Start heartbeat to keep connection alive
   */
  private startHeartbeat(): void {
    this.heartbeatInterval = setInterval(() => {
      if (this.ws && this._connected) {
        try {
          this.ws.send(
            JSON.stringify({
              action: "heartbeat",
            })
          );
        } catch (error) {
          logger.error({ err: error }, "Error sending heartbeat");
        }
      }
    }, this.HEARTBEAT_INTERVAL);
  }

  /**
   * Schedule a reconnection attempt
   */
  private scheduleReconnect(): void {
    if (this.reconnectTimer) {
      return;
    }

    // Check if max retries exceeded
    if (this.reconnectAttempts >= this.MAX_RECONNECT_ATTEMPTS) {
      logger.error(
        { attempts: this.reconnectAttempts },
        "Max reconnection attempts reached. Stopping ticker reconnection. Check credentials and restart server."
      );
      return;
    }

    this.reconnectAttempts++;

    // Exponential backoff: 5s, 10s, 20s, 40s... (capped at 5 minutes)
    const delay = Math.min(
      this.RECONNECT_DELAY * Math.pow(2, this.reconnectAttempts - 1),
      5 * 60 * 1000
    );

    logger.info(
      { delay, attempt: this.reconnectAttempts, maxAttempts: this.MAX_RECONNECT_ATTEMPTS },
      "Scheduling WebSocket reconnect"
    );

    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = undefined;
      this.connect().catch((error) => {
        logger.error({ err: error }, "Reconnection attempt failed");
        // Schedule next attempt with backoff (onClose will also call this)
        this.scheduleReconnect();
      });
    }, delay);
  }
}

export default AngelOneTickerService;

import { randomUUID } from "crypto";
import { HttpError } from "../utils/HttpError";
import type {
  PortfolioPositionSnapshot,
  PortfolioSnapshot,
  Stock,
  Trade,
  TradeSide,
  TradeSummary,
} from "../types";
import type {
  CreateStockRecord,
  CreateTradeRecord,
  PortfolioRepository,
} from "../persistence/PortfolioRepository";
import { RepositoryConflictError } from "../persistence/errors";

export interface CreateStockInput {
  symbol: string;
  name: string;
}

export interface CreateTradeInput {
  symbol: string;
  side: TradeSide;
  quantity: number;
  price: number;
  executedAt?: Date;
  notes?: string;
}

interface PositionState {
  netQuantity: number;
  totalCost: number;
  realizedPnl: number;
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export class PortfolioService {
  constructor(private readonly repository: PortfolioRepository) { }

  public async addStock(input: CreateStockInput): Promise<Stock> {
    const symbol = input.symbol.trim().toUpperCase();
    if (!symbol) {
      throw new HttpError(400, "Stock symbol is required");
    }

    const name = input.name.trim();
    if (!name) {
      throw new HttpError(400, "Stock name is required");
    }

    const record: CreateStockRecord = {
      symbol,
      name,
      createdAt: new Date(),
    };

    try {
      return await this.repository.createStock(record);
    } catch (error) {
      if (error instanceof RepositoryConflictError) {
        throw new HttpError(409, `Stock with symbol ${symbol} already exists`);
      }
      throw error;
    }
  }

  public async listStocks(): Promise<Stock[]> {
    return this.repository.listStocks();
  }

  public async addTrade(input: CreateTradeInput): Promise<Trade> {
    const symbol = input.symbol.trim().toUpperCase();
    if (!symbol) {
      throw new HttpError(400, "Trade symbol is required");
    }

    const stock = await this.repository.findStock(symbol);
    if (!stock) {
      throw new HttpError(404, `Unknown stock symbol ${symbol}`);
    }

    if (!Number.isFinite(input.quantity) || input.quantity <= 0) {
      throw new HttpError(400, "Trade quantity must be a positive number");
    }

    if (!Number.isFinite(input.price) || input.price <= 0) {
      throw new HttpError(400, "Trade price must be a positive number");
    }

    const record: CreateTradeRecord = {
      id: randomUUID(),
      symbol,
      side: input.side,
      quantity: Math.round(input.quantity),
      price: Number(input.price),
      executedAt: input.executedAt ?? new Date(),
      notes: input.notes?.trim() || undefined,
    };

    return this.repository.createTrade(record);
  }

  public async listTrades(): Promise<Trade[]> {
    const trades = await this.repository.listTrades();
    return [...trades].sort((a, b) => b.executedAt.getTime() - a.executedAt.getTime());
  }

  public async recordExternalTrade(trade: Trade): Promise<void> {
    const symbol = trade.symbol.trim().toUpperCase();
    if (!symbol) {
      throw new HttpError(400, "Trade symbol is required");
    }

    await this.repository.ensureStock({ symbol, name: symbol, createdAt: new Date() });

    const id = UUID_PATTERN.test(trade.id) ? trade.id : randomUUID();

    await this.repository.createTradeIfMissing({
      id,
      symbol,
      side: trade.side,
      quantity: Math.round(trade.quantity),
      price: Number(trade.price),
      executedAt: trade.executedAt,
      notes: trade.notes,
    });
  }

  public async getSnapshot(): Promise<PortfolioSnapshot> {
    const trades = await this.repository.listTrades();
    const [summaries, latestPrices] = await Promise.all([
      this.getTradeSummaries(trades),
      this.getLatestTradePrices(trades),
    ]);

    const positions: PortfolioPositionSnapshot[] = summaries.map((summary) => {
      const markPrice = latestPrices.get(summary.symbol) ?? summary.averageEntryPrice;
      const unrealizedPnl = summary.netQuantity * (markPrice - summary.averageEntryPrice);
      return {
        ...summary,
        unrealizedPnl: Number(unrealizedPnl.toFixed(2)),
      } satisfies PortfolioPositionSnapshot;
    });

    return {
      generatedAt: new Date(),
      positions,
      totalTrades: trades.length,
    } satisfies PortfolioSnapshot;
  }

  public async getTradeSummaries(tradesOverride?: Trade[]): Promise<TradeSummary[]> {
    const trades = tradesOverride ?? (await this.repository.listTrades());
    const stocks = await this.repository.listStocks();
    const stockMap = new Map(stocks.map((stock) => [stock.symbol, stock.name]));

    const states = new Map<string, PositionState>();

    for (const trade of trades) {
      const state = states.get(trade.symbol) ?? { netQuantity: 0, totalCost: 0, realizedPnl: 0 };

      if (trade.side === "BUY") {
        let remainingQuantity = trade.quantity;

        const openShortQuantity = Math.max(-state.netQuantity, 0);
        if (openShortQuantity > 0) {
          const closingQuantity = Math.min(openShortQuantity, remainingQuantity);
          if (closingQuantity > 0) {
            const entryAverage = state.netQuantity !== 0 ? state.totalCost / state.netQuantity : 0;
            state.realizedPnl += closingQuantity * (entryAverage - trade.price);
            state.netQuantity += closingQuantity;
            state.totalCost += entryAverage * closingQuantity;
            remainingQuantity -= closingQuantity;

            if (state.netQuantity === 0) {
              state.totalCost = 0;
            }
          }
        }

        if (remainingQuantity > 0) {
          state.totalCost += trade.price * remainingQuantity;
          state.netQuantity += remainingQuantity;
        }
      } else {
        const closingQty = Math.min(Math.max(state.netQuantity, 0), trade.quantity);
        const avgCost = state.netQuantity > 0 ? state.totalCost / state.netQuantity : 0;
        if (closingQty > 0) {
          state.realizedPnl += closingQty * (trade.price - avgCost);
          state.totalCost -= closingQty * avgCost;
          state.netQuantity -= closingQty;
        }

        const residualQty = trade.quantity - closingQty;
        if (residualQty > 0) {
          state.netQuantity -= residualQty;
          state.totalCost -= residualQty * trade.price;
        }
      }

      if (state.netQuantity === 0) {
        state.totalCost = 0;
      }

      states.set(trade.symbol, state);
    }

    return Array.from(states.entries()).map(([symbol, state]) => {
      const position = state.netQuantity > 0 ? "LONG" : state.netQuantity < 0 ? "SHORT" : "FLAT";
      const averageEntryPrice = state.netQuantity !== 0 ? Math.abs(state.totalCost / state.netQuantity) : 0;

      return {
        symbol,
        name: stockMap.get(symbol) ?? symbol,
        netQuantity: state.netQuantity,
        averageEntryPrice: Number(averageEntryPrice.toFixed(4)),
        realizedPnl: Number(state.realizedPnl.toFixed(2)),
        position,
      } satisfies TradeSummary;
    });
  }

  private async getLatestTradePrices(tradesOverride?: Trade[]): Promise<Map<string, number>> {
    const trades = tradesOverride ?? (await this.repository.listTrades());
    const latest = new Map<string, number>();

    for (let index = trades.length - 1; index >= 0; index -= 1) {
      const trade = trades[index];
      if (!latest.has(trade.symbol)) {
        latest.set(trade.symbol, trade.price);
      }
    }

    return latest;
  }

  /**
   * Calculate realized P&L for a specific time period.
   * If fromDate is provided, only includes P&L from trades executed on or after that date.
   * Requires processing full trade history to determine accurate cost basis.
   */
  public async getRealizedPnl(fromDate?: Date): Promise<number> {
    const trades = await this.listTrades(); // Already sorted descending, need ascending for replay
    // Sort ascending for chronological processing
    const chronologicalTrades = [...trades].sort((a, b) => a.executedAt.getTime() - b.executedAt.getTime());

    const states = new Map<string, PositionState>();
    let totalRealizedPnl = 0;

    for (const trade of chronologicalTrades) {
      const state = states.get(trade.symbol) ?? { netQuantity: 0, totalCost: 0, realizedPnl: 0 };
      let tradeRealizedPnl = 0;

      if (trade.side === "BUY") {
        let remainingQuantity = trade.quantity;

        const openShortQuantity = Math.max(-state.netQuantity, 0);
        if (openShortQuantity > 0) {
          // Covering short position
          const closingQuantity = Math.min(openShortQuantity, remainingQuantity);
          if (closingQuantity > 0) {
            const entryAverage = state.netQuantity !== 0 ? state.totalCost / state.netQuantity : 0;
            // Short P&L: (Entry Price - Exit Price) * Quantity
            const pnl = closingQuantity * (entryAverage - trade.price);
            state.realizedPnl += pnl;
            tradeRealizedPnl += pnl;

            state.netQuantity += closingQuantity;
            state.totalCost += entryAverage * closingQuantity; // reducing the negative cost basis
            remainingQuantity -= closingQuantity;

            if (state.netQuantity === 0) {
              state.totalCost = 0;
            }
          }
        }

        if (remainingQuantity > 0) {
          // Opening/Adding long
          state.totalCost += trade.price * remainingQuantity;
          state.netQuantity += remainingQuantity;
        }
      } else {
        // SELL
        const closingQty = Math.min(Math.max(state.netQuantity, 0), trade.quantity);
        const avgCost = state.netQuantity > 0 ? state.totalCost / state.netQuantity : 0;

        if (closingQty > 0) {
          // Closing long P&L: (Exit Price - Entry Price) * Quantity
          const pnl = closingQty * (trade.price - avgCost);
          state.realizedPnl += pnl;
          tradeRealizedPnl += pnl;

          state.totalCost -= closingQty * avgCost;
          state.netQuantity -= closingQty;
        }

        // Remaining sells become short positions
        const residualQty = trade.quantity - closingQty;
        if (residualQty > 0) {
          state.netQuantity -= residualQty;
          state.totalCost -= residualQty * trade.price;
        }
      }

      if (state.netQuantity === 0) {
        state.totalCost = 0;
      }

      states.set(trade.symbol, state);

      // Accumulate if within date range
      if (!fromDate || trade.executedAt >= fromDate) {
        totalRealizedPnl += tradeRealizedPnl;
      }
    }

    return Number(totalRealizedPnl.toFixed(2));
  }
}

export default PortfolioService;

import logger from "../utils/logger";
import { MarketScannerService } from "./MarketScannerService";
import { TradingLoopService } from "./TradingLoopService";
import type TickerClient from "./TickerClient";
import { StopLossMonitor } from "./StopLossMonitor";

/**
 * Service to automate the daily trading lifecycle:
 * 1. Scan market for picks at opening
 * 2. Subscribe to picked stocks
 * 3. Start trading loop and stop-loss monitoring
 */
export class AutoTradingService {
  private static instance: AutoTradingService;
  private scanTimer: NodeJS.Timeout | null = null;

  // Market Pre-Open is at 9:00 AM IST. Normal trading starts at 9:15 AM IST.
  // We scan at 9:00 AM to pick stocks based on yesterday's EOD data and be ready for the open.
  private readonly SCAN_HOUR_IST = 9;
  private readonly SCAN_MINUTE_IST = 0;

  private constructor(
    private readonly scanner: MarketScannerService,
    private readonly tickerClient: TickerClient | null,
    private readonly stopLossMonitor: StopLossMonitor
  ) {}

  public static getInstance(
    scanner?: MarketScannerService,
    tickerClient?: TickerClient | null,
    stopLossMonitor?: StopLossMonitor
  ): AutoTradingService {
    if (!AutoTradingService.instance) {
      if (!scanner || !stopLossMonitor) {
        throw new Error("AutoTradingService not initialized");
      }
      AutoTradingService.instance = new AutoTradingService(scanner, tickerClient || null, stopLossMonitor);
    }
    return AutoTradingService.instance;
  }

  /**
   * Start the auto-trading scheduler
   */
  public start(): void {
    if (this.scanTimer) return;

    const now = new Date();
    const isMarketHours = this.isMarketHours(now);

    if (isMarketHours) {
      logger.info("Service started during market hours. Running initial scan immediately.");
      void this.executeDailyRoutine();
    }

    this.scheduleNextScan();
  }

  /**
   * Schedule the next scan for 9:20 AM IST
   */
  private scheduleNextScan(): void {
    const delay = this.calculateNextScanDelay();

    logger.info(
      { nextScanAt: new Date(Date.now() + delay).toISOString() },
      "Next market scan scheduled"
    );

    this.scanTimer = setTimeout(async () => {
      await this.executeDailyRoutine();
      this.scheduleNextScan(); // Schedule for next day
    }, delay);
  }

  /**
   * Main daily routine: Scan -> Apply -> Trade
   */
  public async executeDailyRoutine(): Promise<void> {
    try {
      logger.info("Executing daily auto-trading routine...");

      // 1. Run Market Scan
      const picks = await this.scanner.scan(10); // Pick top 10

      if (picks.length === 0) {
        logger.warn("No stocks met the criteria today. Trading loop will not be started for new picks.");
        return;
      }

      // 2. Apply picks (Subscribe)
      if (this.tickerClient) {
        await this.scanner.applyPicks(picks, this.tickerClient);
      } else {
        logger.warn("Ticker client not available. Cannot subscribe to picks.");
      }

      // 3. Start Trading Loop
      const tradingLoop = TradingLoopService.getInstance();
      if (!tradingLoop.getStatus().running) {
        tradingLoop.start();
        logger.info("Trading loop started automatically");
      }

      // 4. Start Stop-Loss Monitor
      if (!this.stopLossMonitor.isRunning()) {
        this.stopLossMonitor.start();
        logger.info("Stop-loss monitor started automatically");
      }

      logger.info("Daily auto-trading routine completed successfully");
    } catch (error) {
      logger.error({ err: error }, "Failed to execute daily auto-trading routine");
    }
  }

  private isMarketHours(date: Date): boolean {
    // IST is UTC + 5:30
    const istOffset = 5.5 * 60 * 60 * 1000;
    const istDate = new Date(date.getTime() + istOffset);
    const day = istDate.getUTCDay();
    const hours = istDate.getUTCHours();
    const minutes = istDate.getUTCMinutes();

    // Monday to Friday
    if (day === 0 || day === 6) return false;

    const timeInMinutes = hours * 60 + minutes;
    const marketOpen = 9 * 60 + 15;
    const marketClose = 15 * 60 + 30;

    return timeInMinutes >= marketOpen && timeInMinutes <= marketClose;
  }

  private calculateNextScanDelay(): number {
    const now = new Date();
    const IST_OFFSET_MINUTES = 330; // UTC+5:30
    const scanMinutesIst = this.SCAN_HOUR_IST * 60 + this.SCAN_MINUTE_IST;
    const scanMinutesUtc = (scanMinutesIst - IST_OFFSET_MINUTES + 24 * 60) % (24 * 60);

    const target = new Date(
      Date.UTC(
        now.getUTCFullYear(),
        now.getUTCMonth(),
        now.getUTCDate(),
        Math.floor(scanMinutesUtc / 60),
        scanMinutesUtc % 60,
        0,
        0
      )
    );

    if (target <= now) {
      target.setUTCDate(target.getUTCDate() + 1);
    }

    return target.getTime() - now.getTime();
  }

  public stop(): void {
    if (this.scanTimer) {
      clearTimeout(this.scanTimer);
      this.scanTimer = null;
    }
  }
}

export default AutoTradingService;

