import type { HistoricalCandle, HistoricalDataRequest } from "../types";
import logger from "../utils/logger";

export interface HistoricalDataCache {
  get(key: string): HistoricalCandle[] | undefined;
  set(key: string, data: HistoricalCandle[], ttlMs: number): void;
  clear(): void;
}

class InMemoryCache implements HistoricalDataCache {
  private cache = new Map<string, { data: HistoricalCandle[]; expires: number; lastAccessed: number }>();
  private readonly maxEntries: number;

  constructor(maxEntries: number = 100) {
    this.maxEntries = maxEntries;
  }

  get(key: string): HistoricalCandle[] | undefined {
    const entry = this.cache.get(key);
    if (!entry || Date.now() > entry.expires) {
      this.cache.delete(key);
      return undefined;
    }

    // Update last accessed time for LRU
    entry.lastAccessed = Date.now();
    return entry.data;
  }

  set(key: string, data: HistoricalCandle[], ttlMs: number): void {
    // Evict LRU entry if cache is full
    if (this.cache.size >= this.maxEntries && !this.cache.has(key)) {
      this.evictLRU();
    }

    this.cache.set(key, {
      data,
      expires: Date.now() + ttlMs,
      lastAccessed: Date.now(),
    });
  }

  /**
   * Evict the least recently used entry from cache
   */
  private evictLRU(): void {
    let oldestKey: string | null = null;
    let oldestTime = Infinity;

    for (const [key, entry] of this.cache.entries()) {
      // Also evict expired entries opportunistically
      if (Date.now() > entry.expires) {
        this.cache.delete(key);
        continue;
      }

      if (entry.lastAccessed < oldestTime) {
        oldestTime = entry.lastAccessed;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      logger.debug({ evictedKey: oldestKey }, "Evicted LRU cache entry");
      this.cache.delete(oldestKey);
    }
  }

  clear(): void {
    this.cache.clear();
  }
}

export interface HistoricalDataProvider {
  fetchHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]>;
}

class ZerodhaHistoricalProvider implements HistoricalDataProvider {
  async fetchHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]> {
    logger.info({ symbol: request.symbol, interval: request.interval }, "Fetching historical data from Zerodha");

    // TODO: Implement actual Zerodha historical data API call
    // This would use KiteConnect.getHistoricalData()

    // Mock implementation for now
    const mockData: HistoricalCandle[] = [];
    const startDate = new Date(request.fromDate);
    const endDate = new Date(request.toDate);

    const currentDate = new Date(startDate);
    let price = 100 + Math.random() * 50;

    while (currentDate <= endDate) {
      const dailyChange = (Math.random() - 0.5) * 4; // ±2% daily change
      const open = price;
      const close = price + dailyChange;
      const high = Math.max(open, close) + Math.random() * 2;
      const low = Math.min(open, close) - Math.random() * 2;
      const volume = 10000 + Math.random() * 50000;

      mockData.push({
        symbol: request.symbol,
        open: Number(open.toFixed(2)),
        high: Number(high.toFixed(2)),
        low: Number(low.toFixed(2)),
        close: Number(close.toFixed(2)),
        volume: Math.round(volume),
        timestamp: new Date(currentDate),
      });

      price = close;

      // Increment date based on interval
      if (request.interval === "1day") {
        currentDate.setDate(currentDate.getDate() + 1);
      } else if (request.interval === "1week") {
        currentDate.setDate(currentDate.getDate() + 7);
      } else if (request.interval === "1month") {
        currentDate.setMonth(currentDate.getMonth() + 1);
      }
    }

    return mockData;
  }
}

export class HistoricalDataService {
  private readonly cache: HistoricalDataCache;
  private readonly provider: HistoricalDataProvider;
  private readonly defaultCacheTtl: number;

  constructor(
    cache: HistoricalDataCache = new InMemoryCache(),
    provider: HistoricalDataProvider = new ZerodhaHistoricalProvider(),
    defaultCacheTtlHours = 4
  ) {
    this.cache = cache;
    this.provider = provider;
    this.defaultCacheTtl = defaultCacheTtlHours * 60 * 60 * 1000;
  }

  async getHistoricalData(request: HistoricalDataRequest): Promise<HistoricalCandle[]> {
    const cacheKey = this.buildCacheKey(request);

    // Try cache first
    const cached = this.cache.get(cacheKey);
    if (cached) {
      logger.debug({ symbol: request.symbol, cacheKey }, "Historical data cache hit");
      return cached;
    }

    // Fetch from provider
    logger.info({ symbol: request.symbol, interval: request.interval }, "Fetching historical data");
    const data = await this.provider.fetchHistoricalData(request);

    // Cache the result
    this.cache.set(cacheKey, data, this.defaultCacheTtl);

    return data;
  }

  async getRecentData(symbol: string, days: number = 252): Promise<HistoricalCandle[]> {
    const toDate = new Date();
    const fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - days);

    return this.getHistoricalData({
      symbol,
      interval: "1day",
      fromDate,
      toDate,
    });
  }

  async getWeeklyData(symbol: string, weeks: number = 52): Promise<HistoricalCandle[]> {
    const toDate = new Date();
    const fromDate = new Date();
    fromDate.setDate(fromDate.getDate() - (weeks * 7));

    return this.getHistoricalData({
      symbol,
      interval: "1week",
      fromDate,
      toDate,
    });
  }

  clearCache(): void {
    this.cache.clear();
    logger.info("Historical data cache cleared");
  }

  private buildCacheKey(request: HistoricalDataRequest): string {
    const fromStr = request.fromDate.toISOString().split('T')[0];
    const toStr = request.toDate.toISOString().split('T')[0];
    return `${request.symbol}_${request.interval}_${fromStr}_${toStr}`;
  }
}

export default HistoricalDataService;

import PaperBroker from "./brokers/PaperBroker";
import type BrokerClient from "./brokers/BrokerClient";
import ZerodhaBroker from "./brokers/ZerodhaBroker";
import AngelOneBroker from "./brokers/AngelOneBroker";
import env from "./config/env";
import { getPortfolioRepository, getSettingsRepository, getStopLossRepository, getAuditLogRepository } from "./persistence";
import MarketDataService from "./services/MarketDataService";
import PortfolioService from "./services/PortfolioService";
import TradingEngine from "./services/TradingEngine";
import HistoricalDataService from "./services/HistoricalDataService";
import PortfolioRebalancer from "./services/PortfolioRebalancer";
import ExecutionPlanner from "./services/ExecutionPlanner";
import AngelOneHistoricalProvider from "./providers/AngelOneHistoricalProvider";
import VWAPStrategy from "./strategies/VWAPStrategy";
import type { TickerClient } from "./services/TickerClient";
import AngelOneTickerService from "./services/AngelOneTickerService";
import ReconciliationService from "./services/ReconciliationService";
import { RiskManager } from "./services/RiskManager";
import { StopLossMonitor } from "./services/StopLossMonitor";
import { AuditLogService } from "./services/AuditLogService";
import { HealthService } from "./services/HealthService";
import { NotificationService } from "./services/NotificationService";
import { TunnelService } from "./services/TunnelService";
import { DiscordBotService } from "./services/DiscordBotService";
import { MarketScannerService } from "./services/MarketScannerService";
import type { SettingsRepository } from "./persistence/SettingsRepository";
import type { StopLossRepository } from "./persistence/StopLossRepository";
import type { AuditLogRepository } from "./persistence/AuditLogRepository";

export interface AppContainer {
  portfolioService: PortfolioService;
  marketDataService: MarketDataService;
  historicalDataService: HistoricalDataService;
  marketScannerService: MarketScannerService;
  portfolioRebalancer: PortfolioRebalancer;
  executionPlanner: ExecutionPlanner;
  brokerClient: BrokerClient;
  tradingEngine: TradingEngine;
  tickerClient: TickerClient | null;
  reconciliationService: ReconciliationService;
  settingsRepository: SettingsRepository;
  stopLossRepository: StopLossRepository;
  auditLogRepository: AuditLogRepository;
  riskManager: RiskManager;
  stopLossMonitor: StopLossMonitor;
  auditLogService: AuditLogService;
  healthService: HealthService;
  notificationService: NotificationService;
  tunnelService: TunnelService;
  discordBotService: DiscordBotService;
}

const buildBroker = (): BrokerClient => {
  switch (env.brokerProvider) {
    case "zerodha":
      return new ZerodhaBroker({
        apiKey: env.brokerApiKey,
        apiSecret: env.brokerApiSecret,
        accessToken: env.brokerAccessToken || process.env.ZERODHA_ACCESS_TOKEN,
        requestToken: env.brokerRequestToken,
        defaultExchange: env.brokerDefaultExchange,
        product: env.brokerProduct,
      });
    case "angelone":
      return new AngelOneBroker({
        apiKey: env.angelOneApiKey,
        clientId: env.angelOneClientId,
        password: env.angelOnePassword,
        totpSecret: env.angelOneTotpSecret,
        defaultExchange: env.angelOneDefaultExchange,
        productType: env.angelOneProductType,
      });
    default:
      return new PaperBroker();
  }
};

const buildHistoricalDataService = (): HistoricalDataService => {
  // Use Angel One provider if broker is set to angelone
  if (env.brokerProvider === "angelone" && env.angelOneApiKey) {
    const provider = new AngelOneHistoricalProvider({
      apiKey: env.angelOneApiKey,
      clientId: env.angelOneClientId,
      password: env.angelOnePassword,
      totpSecret: env.angelOneTotpSecret,
    });
    return new HistoricalDataService(undefined, provider);
  }

  // Default to mock provider
  return new HistoricalDataService();
};

/**
 * Build ticker service based on DATA_PROVIDER config
 * Uses Angel One's free WebSocket ticker for real-time market data
 */
const buildTicker = (marketData: MarketDataService): TickerClient | null => {
  // Use Angel One ticker if data provider is set to angelone
  if (env.dataProvider === "angelone" && env.angelOneApiKey) {
    return new AngelOneTickerService(marketData);
  }
  return null;
};

export const createContainer = (): AppContainer => {
  const portfolioService = new PortfolioService(getPortfolioRepository());
  const settingsRepository = getSettingsRepository();
  const stopLossRepository = getStopLossRepository();
  const marketDataService = new MarketDataService();
  const historicalDataService = buildHistoricalDataService();
  const marketScannerService = new MarketScannerService(historicalDataService);
  const portfolioRebalancer = new PortfolioRebalancer();
  const executionPlanner = new ExecutionPlanner();
  const brokerClient = buildBroker();
  const riskManager = new RiskManager(settingsRepository);
  const tradingEngine = new TradingEngine({
    broker: brokerClient,
    marketData: marketDataService,
    portfolioService,
    riskManager,
  });

  tradingEngine.registerStrategy(new VWAPStrategy());

  // Build ticker for real-time market data (uses DATA_PROVIDER config)
  const tickerClient = buildTicker(marketDataService);

  // Build reconciliation service for syncing with broker
  const reconciliationService = new ReconciliationService(brokerClient, portfolioService);

  // Build stop-loss monitor
  const stopLossMonitor = new StopLossMonitor({
    marketDataService,
    tradingEngine,
    stopLossRepository,
    riskManager,
  });

  // Build audit log service
  const auditLogRepository = getAuditLogRepository();
  const auditLogService = new AuditLogService({
    repository: auditLogRepository,
    tradingEngine,
    stopLossMonitor,
    settingsRepository,
  });

  // Build health service
  const healthService = new HealthService({
    brokerClient,
    tickerClient: tickerClient || undefined,
    marketDataService,
    stopLossMonitor,
  });

  // Build notification service (only if webhook configured)
  const notificationService = new NotificationService({
    discordWebhookUrl: env.discordWebhookUrl,
    webhookUrl: env.webhookUrl,
    tradingEngine,
    stopLossMonitor,
  });

  // Wire RiskManager critical errors to notifications
  riskManager.on("critical_error", (event: { type: string; error: Error }) => {
    void notificationService.notifyCriticalError(
      event.type,
      event.error?.message || "Unknown error"
    );
  });

  // Build remote access services
  const tunnelService = new TunnelService();

  const discordBotService = new DiscordBotService({
    token: env.discordBotToken,
    tunnelService,
  });

  return {
    portfolioService,
    marketDataService,
    historicalDataService,
    marketScannerService,
    portfolioRebalancer,
    executionPlanner,
    brokerClient,
    tradingEngine,
    tickerClient,
    reconciliationService,
    settingsRepository,
    stopLossRepository,
    auditLogRepository,
    riskManager,
    stopLossMonitor,
    auditLogService,
    healthService,
    notificationService,
    tunnelService,
    discordBotService,
  };
};

let activeContainer: AppContainer | null = null;

export const getContainer = (): AppContainer => {
  if (!activeContainer) {
    activeContainer = createContainer();
  }

  return activeContainer;
};

export const resetContainer = (): AppContainer => {
  activeContainer = createContainer();
  return activeContainer;
};

// For testing purposes
export const setContainer = (container: AppContainer): void => {
  activeContainer = container;
